input.command:
S=/private/tmp/claude-501/-Users-merill-github-maester/437be988-30b4-4776-8721-ab0b0e1cc2b3/scratchpad; mkdir -p $S/tools; cat > $S/tools/frames.swift <<'EOF'
import AVFoundation
import AppKit
let args = CommandLine.arguments
let asset = AVURLAsset(url: URL(fileURLWithPath: args[1]))
let out = args[2]
let n = Int(args[3])!
let dur = CMTimeGetSeconds(asset.duration)
print("duration", dur)
let gen = AVAssetImageGenerator(asset: asset)
gen.appliesPreferredTrackTransform = true
gen.requestedTimeToleranceBefore = .zero
gen.requestedTimeToleranceAfter = .zero
for i in 0..<n {
  let t = CMTime(seconds: dur * Double(i) / Double(n), preferredTimescale: 600)
  if let cg = try? gen.copyCGImage(at: t, actualTime: nil) {
    let rep = NSBitmapImageRep(cgImage: cg)
    let data = rep.representation(using: .png, properties: [:])!
    try! data.write(to: URL(fileURLWithPath: String(format: "%@/f%02d.png", out, i)))
    if i == 0 { print("size", cg.width, cg.height) }
  }
}
EOF
cd $S && swift tools/frames.swift video/console.mp4 frames 16 2>&1 | tail -3; ls frames

