/// <summary>The main column in plain lines, on a console that is short of rows or columns for its boxes.</summary>
private List<Line> BuildPlainMain(int max, int rows, bool ansi)
{
    Func<Line> blank = Blank;
    bool tests = _running || _total > 0;
    bool info = _info != null;

    // The phases of the run, on one line.
    Line phases = null;
    if (_phases.Count > 0)
    {
        var strip = new LineBuilder(ansi).Add(" ");
        for (int i = 0; i < _phases.Count; i++)
        {
            var p = _phases[i];
            if (p.Done) strip.Add(Ok, "32").Add(" " + p.Name + (p.Clock != null ? " " + Short(p.Clock.Elapsed) : string.Empty), "2");
            else if (p.Clock != null) strip.Add(Unicode ? "●" : "*", Amber).Add(" " + p.Name, "1").Add(" " + Short(p.Clock.Elapsed), Amber);
            else strip.Add(Unicode ? "○" : "o", "2").Add(" " + p.Name, "2");
            if (i < _phases.Count - 1) strip.Add(Unicode ? "  ─  " : "  -  ", "2");
        }
        phases = Truncate(strip.Build(), max, ansi);
    }

    // While tests run the top of the screen is a band of five rows: the small logo, and the Pace graph
    // to its right. It needs a console of some size; a smaller one gets one line.
    bool band = (tests || OutputTimed) && _runLogo != null && rows >= RunBandLeastRows && max >= _runLogoWidth + 3 + RunBandLeastGraph;

    // Before the tests start the phases have a line under the banner. Once they run, the phases are
    // right above the overall progress (under the band), or in the header when that is one line.
    var body = new List<Line>();
    if (!tests && phases != null)
    {
        body.Add(phases);
        body.Add(blank());
    }
    if (band && tests && phases != null) body.Add(phases);
    if (tests)
    {
        int done = FinishedCount();
        var overall = new LineBuilder(ansi).Add(" ");
        AddBar(overall, done, _total, Math.Max(10, Math.Min(40, max - 52) + Math.Max(0, max - (MainWidth - 1))));
        overall.Add("  " + ProgressText(done, CurrentPhaseClock(), false), "1").Add("   ");
        AddCounts(overall, _passed, _failed, _error, _investigate, _skipped);
        body.Add(Truncate(overall.Build(), max, ansi));
        body.Add(blank());
    }

    // What is running now: one line per test, so it reads the same with one worker or many.
    var tail = new List<Line>();
    if (_running)
    {
        tail.Add(new LineBuilder(ansi).Add(" Running", "1").Add(_workers.Count > 1 ? " · " + N(_workers.Count) + " tests" : string.Empty, "2").Build());
        tail.AddRange(BuildWorkerLines(max, " ", ansi));
    }
    else if (_status != null)
    {
        tail.Add(new LineBuilder(ansi).Add(" " + Spinner() + " ", "36").Add(_status + Ellipsis()).Build());
    }

    // Header. While the run prepares: the banner, when it fits next to everything else. Once the tests
    // start the banner makes room for them: the band with the small logo and the Pace graph, or one line
    // with the name, the version and the phases.
    var header = new List<Line>();
    // A lane whose tests were all skipped has nothing to show in a row of its own: those lanes share
    // one line, by name and number of tests. That is a lane whose tests all finished as skipped, and a
    // lane that the run gave no tests and the note "n skipped" (its service is not connected).
    var skippedLanes = tests ? SkippedLanes() : new List<Lane>();
    int lanesWanted = tests ? Lanes.Count - skippedLanes.Count + (skippedLanes.Count > 0 ? 1 : 0) : 0;
    bool output = _outputTitle != null;
    int needed = body.Count + tail.Count + 2 + (info ? 1 : 0) + (output && !tests ? OutputOpeningRows : 0);
    if (band) header.AddRange(BuildRunBand(max, ansi));
    else if (tests) header.AddRange(BuildRunHeader(max, phases, ansi));
    else header.AddRange(BuildOpeningHeader(max, rows, needed, ansi));
    if (info) header.Add(BuildInfoLine(max, ansi));
    header.Add(blank());

    // The insight panels keep their place while the tests run: one row of them, and the tests that ran
    // last, have rows set aside when the screen has them next to the lanes, a row of result blocks and
    // three running tests. The list of running tests then stops where those rows start, and says how
    // many more are running.
    int reserve = 0;
