        public void SetStatusBar(string[] labels, string[] links)
        {
            SetStatusBar(labels, links, 0);
        }

        /// <summary>
        /// The same, with the last <paramref name="rightAligned"/> labels at the right edge of the window and the
        /// others at the left, so that the bar spans the whole width.
        /// </summary>
        public void SetStatusBar(string[] labels, string[] links, int rightAligned)
        {
            lock (_gate)
            {
                _barLabels.Clear();
                _barLinks.Clear();
                int count = labels == null ? 0 : labels.Length;
                for (int i = 0; i < count; i++)
                {
                    _barLabels.Add(PlainText(labels[i]) ?? string.Empty);
                    _barLinks.Add(links != null && i < links.Length ? links[i] : null);
                }
                _barRight = Math.Max(0, Math.Min(rightAligned, _barLabels.Count));
                Redraw();
            }
        }

        /// <summary>
        /// A hint in the middle of the status bar, between its two groups ("⌘-click to open"). It is left out when
        /// there is no room for it. Null for none.
        /// </summary>
        public void SetStatusBarHint(string hint)
        {
            lock (_gate)
            {
                _barHint = PlainText(hint);
                Redraw();
            }
        }

        /// <summary>
        /// The status bar: the labels of the left group from the left edge and those of the right group up to the
        /// right edge, with the background between them. In a window that is too narrow for all of them the right
        /// group goes first, from its left, and then the left group from its right.
        /// </summary>
        private Line BuildStatusBar(int width, bool ansi)
        {
            int max = Math.Max(1, width - 1);
            int leftCount = _barLabels.Count - _barRight;
            int used = 0;
            var left = new List<int>();
            for (int i = 0; i < leftCount; i++)
            {
                int need = BarSegmentWidth(i, left.Count);
                if (used + need > max) break;
                left.Add(i);
                used += need;
            }
            // The right group, from its last label back, in the room that is left (and a gap of two columns).
            var right = new List<int>();
            for (int i = _barLabels.Count - 1; i >= leftCount && left.Count == leftCount; i--)
            {
                int need = _barLabels[i].Length + 2 + (right.Count > 0 ? 1 : 0);
                if (used + need + 2 > max) break;
                right.Insert(0, i);
                used += need;
            }
            // The text of the bar, and for each column the label it belongs to (or -1).
            var plain = new StringBuilder();
            var owner = new List<int>();
            for (int n = 0; n < left.Count; n++) AppendBarSegment(plain, owner, left[n], n > 1);
            // Between the groups: the hint in the middle, when it fits with two columns on each side.
            int gap = max - used;
            if (!string.IsNullOrEmpty(_barHint) && _barHint.Length + 4 <= gap)
            {
                int before = (gap - _barHint.Length) / 2;
                plain.Append(' ', before).Append(_barHint).Append(' ', gap - before - _barHint.Length);
            }
            else
            {
                plain.Append(' ', gap);
            }
            while (owner.Count < plain.Length) owner.Add(-1);
            for (int n = 0; n < right.Count; n++) AppendBarSegment(plain, owner, right[n], n > 0);
            if (!ansi) return new Line { Text = plain.ToString(), Plain = plain.ToString() };

            // The colours of the wordmark, from left to right, behind the text; each label is a hyperlink.
            var text = new StringBuilder();
            string colour = null;
            int link = -1;
            for (int x = 0; x < plain.Length; x++)
            {
                if (owner[x] != link)
                {
                    if (link >= 0 && !string.IsNullOrEmpty(_barLinks[link])) text.Append(LinkEnd);
                    link = owner[x];
                    if (link >= 0 && !string.IsNullOrEmpty(_barLinks[link])) text.Append(Esc8).Append(_barLinks[link]).Append("\u001b\\");
                }
                string want = BarColour(x, plain.Length, owner[x] == 0);
                if (want != colour)
                {
                    text.Append(Esc).Append(want).Append('m');
                    colour = want;
                }
                text.Append(plain[x]);
            }
            if (link >= 0 && !string.IsNullOrEmpty(_barLinks[link])) text.Append(LinkEnd);
            text.Append(Esc).Append("0m");
            return new Line { Text = text.ToString(), Plain = plain.ToString() };
        }

        private static readonly int[][] BarStops = { new[] { 229, 36, 59 }, new[] { 255, 106, 61 }, new[] { 255, 181, 71 } };

        /// <summary>
        /// The colours of a column of the status bar: the gradient of the wordmark (Maester red to amber) behind
        /// white text where it is dark and dark text where it is light. Without true colour the bar is one
        /// orange, with dark text.
        /// </summary>
        private string BarColour(int column, int columns, bool bold)
        {
            string weight = bold ? "1;" : "22;";
            if (!TrueColor) return weight + "38;5;232;48;5;208";
            double t = columns > 1 ? (double)column / (columns - 1) * (BarStops.Length - 1) : 0;
            int segment = Math.Min((int)t, BarStops.Length - 2);
            var rgb = new int[3];
            for (int i = 0; i < 3; i++) rgb[i] = (int)(BarStops[segment][i] + (BarStops[segment + 1][i] - BarStops[segment][i]) * (t - segment));
            double luminance = 0.2126 * rgb[0] + 0.7152 * rgb[1] + 0.0722 * rgb[2];
            string fg = luminance < 125 ? "38;2;255;255;255" : "38;2;43;13;6";
            return weight + fg + ";48;2;" + N(rgb[0]) + ";" + N(rgb[1]) + ";" + N(rgb[2]);
        }

        /// <summary>The columns a label of the left group takes: a space on each side, and a separator from the third on.</summary>
        private int BarSegmentWidth(int index, int position)
        {
            return _barLabels[index].Length + 2 + (position > 1 ? 1 : 0);
        }

        private void AppendBarSegment(StringBuilder plain, List<int> owner, int index, bool separator)
        {
            if (separator)
            {
                plain.Append(Unicode ? "│" : "|");
                owner.Add(-1);
            }
            string label = " " + _barLabels[index] + " ";
            plain.Append(label);
            for (int i = 0; i < label.Length; i++) owner.Add(index);
        }

        private const int IdWidth = 15;

        /// <summary>
        /// A test ID in the column the lists have for it: fifteen characters, which fits all but a few of the
        /// IDs. A longer one is cut in its middle, because what tells two IDs apart is at the end
        /// (CISA.MS.SHAREPOINT.1.1 becomes CISA.MS…INT.1.1).
        /// </summary>
        private string FitId(string id)
        {
            id = id ?? string.Empty;
            if (id.Length <= IdWidth) return id.PadRight(IdWidth);
            int tail = (IdWidth - 1) / 2;
            return id.Substring(0, IdWidth - 1 - tail) + (Unicode ? "…" : ".") + id.Substring(id.Length - tail);
            return false;
        }

